style.css:
@-moz-document domain("huggingface.co") {
body {
    background-color: transparent !important;
    color: white !important;
  }

  body::before {
    content: "" !important;
    position: fixed !important;
    inset: 0 !important;
    z-index: -1 !important;
    background-image: url("https://cdn.discordapp.com/attachments/1452943520271962236/1494958711284957295/Pudding_a_la_mode_gacha_background.png?ex=69e5290b&is=69e3d78b&hm=5318e25f25555853ac67935791d3f19dd5fa817efd566ed42884eea7472ed91e") !important;
    background-size: cover !important;
    background-position: center !important;
  }

  .bg-white,
  .dark\:bg-gray-950,
  [class*="from-gray-50"],
  [class*="bg-gray-9"],
  [class*="bg-gray-8"],
  [class*="bg-gray-1"],
  [class*="bg-gray-2"] {
    background-color: transparent !important;
    background-image: none !important;
  }

  * {
    color: white !important;
    text-shadow: 0 1px 3px rgba(0,0,0,0.6) !important;
  }

  a, h1, h2, h3, h4, p, span, li, div {
    color: white !important;
  }
}
